import nbformat as nbf, pathlib
SOL = (pathlib.Path(__file__).resolve().parents[1] / "contracts" / "CredentialRegistry.sol").read_text()
nb = nbf.v4.new_notebook(); C = []
md = lambda s: C.append(nbf.v4.new_markdown_cell(s)); code = lambda s: C.append(nbf.v4.new_code_cell(s))
md("# Praktikum: Kredensial Mikro Terverifikasi Blockchain + Analitik Pembelajaran\nPendamping monograf *Kredensial Mikro Terverifikasi Blockchain* (judul kerja). Berjalan di Google Colab atau Jupyter lokal tanpa node blockchain eksternal (memakai **eth-tester**).\n\n**Tujuan:** (1) mengompilasi dan menyebarkan smart contract registri kredensial; (2) menerbitkan, memverifikasi, dan mencabut kredensial berformat W3C VC 2.0/Open Badges 3.0; (3) mengukur gas; (4) melatih model prediksi capaian dini dengan OULAD.")
code("import importlib, subprocess, sys\nfor pkg, mod in [('py-solc-x','solcx'),('web3','web3'),('eth-tester[py-evm]','eth_tester'),('scikit-learn','sklearn'),('pandas','pandas'),('matplotlib','matplotlib')]:\n    try: importlib.import_module(mod)\n    except ImportError: subprocess.check_call([sys.executable,'-m','pip','install','-q',pkg])\nprint('paket siap')")
md("## 1. Kompilasi smart contract")
code("SOURCE = r'''" + SOL + "'''\nimport solcx\nsolcx.install_solc('0.8.24')\nout = solcx.compile_source(SOURCE, output_values=['abi','bin'], solc_version='0.8.24', optimize=True)\n_, art = next((k,v) for k,v in out.items() if k.endswith(':CredentialRegistry'))\nprint('ukuran bytecode:', len(art['bin'])//2, 'byte')")
md("## 2. Blockchain uji dalam memori dan deploy")
code("from web3 import Web3\nfrom web3.providers.eth_tester import EthereumTesterProvider\nw3 = Web3(EthereumTesterProvider()); admin, issuer, lain = w3.eth.accounts[:3]\nC = w3.eth.contract(abi=art['abi'], bytecode=art['bin'])\nrc = w3.eth.wait_for_transaction_receipt(C.constructor().transact({'from': admin}))\nreg = w3.eth.contract(address=rc.contractAddress, abi=art['abi'])\nprint('kontrak:', reg.address, '| gas deploy:', rc.gasUsed)\nrc = w3.eth.wait_for_transaction_receipt(reg.functions.addIssuer(issuer, 'Lembaga Praktikum').transact({'from': admin}))\nprint('gas addIssuer:', rc.gasUsed)")
md("## 3. Membuat kredensial VC 2.0 / Open Badges 3.0 dan menghitung hash")
code("import json, uuid, datetime\nfrom eth_utils import keccak\ndef kredensial(nama, capaian):\n    return {'@context':['https://www.w3.org/ns/credentials/v2','https://purl.imsglobal.org/spec/ob/v3p0/context-3.0.3.json'],\n            'id':f'urn:uuid:{uuid.uuid4()}','type':['VerifiableCredential','OpenBadgeCredential'],\n            'issuer':{'id':f'did:pkh:eip155:{w3.eth.chain_id}:{issuer}','type':['Profile'],'name':'Lembaga Praktikum'},\n            'validFrom':datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ'),\n            'credentialSubject':{'type':['AchievementSubject'],'name':nama,'achievement':{'type':['Achievement'],'name':capaian}}}\ndef h(c): return keccak(json.dumps(c, sort_keys=True, separators=(',',':')).encode())\nk = kredensial('Peserta A', 'Dasar Smart Contract'); print(json.dumps(k, indent=1)[:400]); print('hash:', h(k).hex())")
md("## 4. Terbitkan, verifikasi, rusak, dan cabut")
code("gas = {}\nrc = w3.eth.wait_for_transaction_receipt(reg.functions.issue(h(k), keccak(b'peserta-a')).transact({'from': issuer})); gas['issue'] = rc.gasUsed\nprint('verifikasi asli  :', reg.functions.verify(h(k)).call())\npalsu = json.loads(json.dumps(k)); palsu['credentialSubject']['name'] = 'Peserta B'\nprint('verifikasi palsu :', reg.functions.verify(h(palsu)).call()[0])\nrc = w3.eth.wait_for_transaction_receipt(reg.functions.revoke(h(k), 'uji').transact({'from': issuer})); gas['revoke'] = rc.gasUsed\nprint('setelah dicabut  :', reg.functions.verify(h(k)).call()); print('gas:', gas)")
md("## 5. Biaya gas: penerbitan per kredensial vs akar Merkle")
code("def mroot(leaves):\n    L = list(leaves)\n    while len(L) > 1:\n        L = [ (keccak(min(L[i],L[i+1])+max(L[i],L[i+1])) if i+1 < len(L) else L[i]) for i in range(0, len(L), 2)]\n    return L[0]\nimport pandas as pd\nrows = []\nfor n in [1, 5, 10, 20, 50]:\n    hs = [keccak(f'b{n}-{i}'.encode()) for i in range(n)]\n    g1 = w3.eth.wait_for_transaction_receipt(reg.functions.issueBatch(hs, b'\\x00'*32).transact({'from': issuer})).gasUsed\n    hs2 = [keccak(f'm{n}-{i}'.encode()) for i in range(n)]\n    g2 = w3.eth.wait_for_transaction_receipt(reg.functions.anchorBatchRoot(mroot(hs2), n).transact({'from': issuer})).gasUsed\n    rows.append({'n': n, 'gas/kred (issueBatch)': g1/n, 'gas/kred (Merkle)': g2/n})\ndf = pd.DataFrame(rows); df")
md("## 6. Analitik pembelajaran dengan OULAD\nSumber: Kuzilek dkk. (2017), *Scientific Data* 4:170171, doi:10.1038/sdata.2017.171; salinan di UCI Machine Learning Repository (CC BY 4.0). Bila unduhan gagal, sel ini memakai **DATA SINTETIS** yang ditandai jelas.")
code("import io, zipfile, urllib.request, numpy as np\nURL = 'https://archive.ics.uci.edu/static/public/349/open+university+learning+analytics+dataset.zip'\ntry:\n    z = zipfile.ZipFile(io.BytesIO(urllib.request.urlopen(URL, timeout=120).read()))\n    info = pd.read_csv(z.open('studentInfo.csv')); sa = pd.read_csv(z.open('studentAssessment.csv')); asm = pd.read_csv(z.open('assessments.csv'))\n    sa = sa.merge(asm, on='id_assessment'); sa = sa[sa.date_submitted <= 60]; sa['score'] = pd.to_numeric(sa.score, errors='coerce')\n    key = ['code_module','code_presentation','id_student']\n    f = sa.groupby(key).agg(mean_score=('score','mean'), n_submit=('score','count')).reset_index()\n    df = info.merge(f, on=key, how='left').fillna({'mean_score':0,'n_submit':0})\n    df['y'] = df.final_result.isin(['Pass','Distinction']).astype(int); SUMBER = 'OULAD'\nexcept Exception as e:\n    print('unduhan gagal -> DATA SINTETIS:', e); r = np.random.default_rng(0)\n    df = pd.DataFrame({'mean_score': r.uniform(0,100,3000), 'n_submit': r.integers(0,4,3000), 'num_of_prev_attempts': r.integers(0,3,3000), 'studied_credits': r.choice([30,60,120],3000)})\n    df['y'] = (r.uniform(size=3000) < 1/(1+np.exp(-(0.04*df.mean_score+0.4*df.n_submit-3)))).astype(int); SUMBER = 'SINTETIS'\nprint(SUMBER, df.shape)")
code("from sklearn.model_selection import train_test_split\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.metrics import roc_auc_score, f1_score\nX = df[['mean_score','n_submit','num_of_prev_attempts','studied_credits']].values; y = df.y.values\nXtr, Xte, ytr, yte = train_test_split(X, y, test_size=.25, random_state=42, stratify=y)\nm = RandomForestClassifier(n_estimators=200, min_samples_leaf=5, random_state=42, n_jobs=-1).fit(Xtr, ytr)\np = m.predict_proba(Xte)[:,1]\nprint(f'[{SUMBER}] AUC = {roc_auc_score(yte,p):.3f} | F1 = {f1_score(yte,p>=.5):.3f}')")
md("## 7. Melampirkan bukti analitik ke kredensial\nProbabilitas capaian dimasukkan sebagai `evidence`, lalu hash kredensial dijangkarkan.")
code("k2 = kredensial('Peserta C', 'Analitik Data Pendidikan'); k2['evidence'] = [{'type':['Evidence'], 'name':'Bukti analitik', 'description': f'p(lulus)={p[0]:.2f}; model RF; data {SUMBER}'}]\nrc = w3.eth.wait_for_transaction_receipt(reg.functions.issue(h(k2), keccak(b'peserta-c')).transact({'from': issuer}))\nprint('terbit dengan bukti, gas', rc.gasUsed, '| valid:', reg.functions.verify(h(k2)).call()[0])")
md("## Latihan\n1. Ubah kanonikalisasi menjadi JCS (RFC 8785) dan bandingkan hash.\n2. Tambahkan fungsi `suspend` pada kontrak dan unit test-nya.\n3. Bandingkan model dengan batas hari 30 vs 90.")
nb["cells"] = C; nb.metadata["kernelspec"] = {"name": "python3", "display_name": "Python 3", "language": "python"}
nbf.write(nb, pathlib.Path(__file__).with_name("Praktikum_Kredensial_Blockchain.ipynb"))
